import (
	"encoding/json"
	"net/http"

	"shop/catalogue"
)

// Addr is where the service listens: the catalogue's port, the only one the shop has.
func Addr() string { return ":" + itoa(catalogue.DefaultPort) }

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b [20]byte
	i := len(b)
	for ; n > 0; n /= 10 {
		i--
		b[i] = byte('0' + n%10)
	}
	return string(b[i:])
}

